window.PAGES["day1-lab"] = {"title": "OCI IAM Lab Visualizer \u2014 Day 1 | 1Z0-1067-26", "css": "\n:host{\n  --bg:#0d1117; --bg2:#11161d; --panel:#151b23; --panel2:#1a212b;\n  --border:#232b36; --border-soft:#1d2530;\n  --text:#e6ebf1; --text-dim:#9aa7b6; --text-faint:#5f6b7a;\n  --red:#ff3b30; --red-dim:#c62b22; --red-glow:rgba(255,59,48,.25);\n  --blue:#4da3ff; --blue-dim:#2f6fd1;\n  --orange:#ffab40; --green:#3ddc84; --green-dim:#279a5c;\n  --yellow:#ffd54a; --purple:#b48bff;\n  --radius:14px; --radius-sm:9px;\n  --shadow: 0 8px 30px rgba(0,0,0,.35);\n  --mono: 'SFMono-Regular', Consolas, 'Courier New', monospace;\n  --sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Inter, Roboto, Helvetica, Arial, sans-serif;\n}\n[data-theme=\"light\"]{\n  --bg:#f4f5f7; --bg2:#eceef1; --panel:#ffffff; --panel2:#f7f8fa;\n  --border:#e1e4e9; --border-soft:#ebedf0;\n  --text:#1b2129; --text-dim:#5b6572; --text-faint:#8b95a3;\n  --red:#e0342a; --red-dim:#c62b22; --red-glow:rgba(224,52,42,.18);\n  --shadow: 0 8px 30px rgba(20,20,30,.08);\n}\n*{box-sizing:border-box; margin:0; padding:0;}\n:host{scroll-behavior:smooth;}\n:host{\n  background:var(--bg); color:var(--text); font-family:var(--sans);\n  min-height:100%; overflow-x:hidden; transition:background .3s,color .3s;\n}\nbody::before{\n  content:''; position:fixed; inset:0; pointer-events:none; z-index:0;\n  background:\n    radial-gradient(circle at 15% 10%, var(--red-glow), transparent 40%),\n    radial-gradient(circle at 85% 90%, rgba(77,163,255,.10), transparent 45%);\n}\n::-webkit-scrollbar{width:10px; height:10px;}\n::-webkit-scrollbar-track{background:transparent;}\n::-webkit-scrollbar-thumb{background:var(--border); border-radius:10px;}\n::-webkit-scrollbar-thumb:hover{background:var(--text-faint);}\n\na{color:inherit;}\nbutton{font-family:inherit; cursor:pointer;}\n\n/* ---------- Top Bar ---------- */\n.topbar{\n  position:sticky; top:0; z-index:100;\n  display:flex; align-items:center; gap:14px;\n  padding:10px 18px; background:color-mix(in srgb, var(--panel) 88%, transparent);\n  backdrop-filter:blur(14px); border-bottom:1px solid var(--border-soft);\n}\n.brand{display:flex; align-items:center; gap:10px; font-weight:700; letter-spacing:.2px;}\n.brand .logo{\n  width:30px; height:30px; border-radius:8px;\n  background:linear-gradient(135deg, var(--red), var(--red-dim));\n  display:flex; align-items:center; justify-content:center; font-size:14px; color:#fff; font-weight:800;\n  box-shadow:0 4px 14px var(--red-glow);\n}\n.brand small{display:block; font-weight:500; color:var(--text-faint); font-size:10.5px; letter-spacing:.5px;}\n.crumb{display:flex; align-items:center; gap:6px; font-size:12.5px; color:var(--text-dim); flex:1; min-width:0; overflow:hidden; white-space:nowrap;}\n.crumb b{color:var(--text); font-weight:600;}\n.topbar-right{display:flex; align-items:center; gap:10px;}\n.xp-chip{\n  display:flex; align-items:center; gap:7px; background:var(--panel2); border:1px solid var(--border);\n  padding:6px 12px; border-radius:20px; font-size:12.5px; font-weight:600;\n}\n.xp-chip .dot{width:7px; height:7px; border-radius:50%; background:var(--orange); box-shadow:0 0 8px var(--orange);}\n.rank-chip{\n  background:linear-gradient(135deg, var(--red), var(--red-dim)); color:#fff; font-size:11.5px; font-weight:700;\n  padding:6px 11px; border-radius:20px; letter-spacing:.3px;\n}\n.icon-btn{\n  width:34px; height:34px; border-radius:9px; border:1px solid var(--border); background:var(--panel2);\n  color:var(--text-dim); display:flex; align-items:center; justify-content:center; font-size:15px;\n  transition:.15s;\n}\n.icon-btn:hover{color:var(--text); border-color:var(--text-faint);}\n\n/* ---------- Layout ---------- */\n.app{display:flex; min-height:calc(100% - 54px); position:relative; z-index:1;}\n.sidebar{\n  width:250px; flex-shrink:0; border-right:1px solid var(--border-soft);\n  padding:16px 10px; position:sticky; top:54px; height:calc(100% - 54px); overflow-y:auto;\n  background:color-mix(in srgb, var(--bg2) 60%, transparent);\n}\n.sidebar h4{font-size:10.5px; text-transform:uppercase; letter-spacing:1px; color:var(--text-faint); padding:14px 10px 6px;}\n.nav-item{\n  display:flex; align-items:center; gap:10px; padding:9px 10px; border-radius:9px; font-size:13px;\n  color:var(--text-dim); cursor:pointer; transition:.15s; margin-bottom:2px; border:1px solid transparent;\n  position:relative;\n}\n.nav-item .n-ico{width:22px; text-align:center; font-size:13px; flex-shrink:0;}\n.nav-item:hover{background:var(--panel2); color:var(--text);}\n.nav-item.active{background:var(--red-glow); color:var(--text); border-color:var(--red-dim); font-weight:600;}\n.nav-item.locked{opacity:.4; cursor:not-allowed;}\n.nav-item.done .n-ico{color:var(--green);}\n.nav-badge{margin-left:auto; font-size:10px; background:var(--panel); border:1px solid var(--border); padding:1px 6px; border-radius:8px; color:var(--text-faint);}\n.nav-item.done .nav-badge{color:var(--green); border-color:var(--green-dim);}\n\n.progress-mini{margin:10px 8px 4px; padding:10px; background:var(--panel); border:1px solid var(--border); border-radius:10px;}\n.progress-mini .lbl{display:flex; justify-content:space-between; font-size:11px; color:var(--text-dim); margin-bottom:6px;}\n.bar-track{height:6px; border-radius:5px; background:var(--border-soft); overflow:hidden;}\n.bar-fill{height:100%; background:linear-gradient(90deg, var(--red), var(--orange)); border-radius:5px; transition:width .5s ease;}\n\n.main{flex:1; min-width:0; padding:26px 30px 80px;}\n.view{display:none; animation:fadeIn .35s ease;}\n.view.active{display:block;}\n@keyframes fadeIn{from{opacity:0; transform:translateY(8px);} to{opacity:1; transform:translateY(0);}}\n\n.section-head{margin-bottom:22px;}\n.eyebrow{font-size:11px; text-transform:uppercase; letter-spacing:1.5px; color:var(--red); font-weight:700; margin-bottom:6px;}\nh1.page-title{font-size:26px; font-weight:800; letter-spacing:-.3px;}\n.page-sub{color:var(--text-dim); font-size:13.5px; margin-top:5px; max-width:680px;}\n\n.card{\n  background:var(--panel); border:1px solid var(--border); border-radius:var(--radius);\n  padding:20px; box-shadow:var(--shadow);\n}\n.grid{display:grid; gap:16px;}\n.grid-2{grid-template-columns:1fr 1fr;}\n.grid-3{grid-template-columns:repeat(3,1fr);}\n.grid-4{grid-template-columns:repeat(4,1fr);}\n@media(max-width:1000px){.grid-2,.grid-3,.grid-4{grid-template-columns:1fr;}}\n\n.btn{\n  display:inline-flex; align-items:center; gap:8px; padding:11px 20px; border-radius:10px; border:none;\n  font-weight:700; font-size:13.5px; transition:.15s;\n}\n.btn-primary{background:linear-gradient(135deg,var(--red),var(--red-dim)); color:#fff; box-shadow:0 6px 20px var(--red-glow);}\n.btn-primary:hover{transform:translateY(-1px); box-shadow:0 10px 26px var(--red-glow);}\n.btn-ghost{background:var(--panel2); color:var(--text); border:1px solid var(--border);}\n.btn-ghost:hover{border-color:var(--text-faint);}\n.btn-sm{padding:7px 13px; font-size:12px; border-radius:8px;}\n.btn:disabled{opacity:.4; cursor:not-allowed; transform:none !important;}\n\n.pill{display:inline-flex; align-items:center; gap:5px; font-size:11px; font-weight:700; padding:3px 9px; border-radius:20px;}\n.pill-green{background:rgba(61,220,132,.14); color:var(--green);}\n.pill-red{background:rgba(255,59,48,.14); color:var(--red);}\n.pill-orange{background:rgba(255,171,64,.14); color:var(--orange);}\n.pill-blue{background:rgba(77,163,255,.14); color:var(--blue);}\n.pill-gray{background:var(--panel2); color:var(--text-faint); border:1px solid var(--border);}\n\n/* Toast */\n#toast-wrap{position:fixed; bottom:22px; right:22px; z-index:9999; display:flex; flex-direction:column; gap:10px;}\n.toast{\n  background:var(--panel); border:1px solid var(--border); border-radius:12px; padding:13px 16px;\n  box-shadow:var(--shadow); display:flex; align-items:center; gap:10px; min-width:260px;\n  animation:toastIn .3s ease; font-size:13px;\n}\n@keyframes toastIn{from{opacity:0; transform:translateX(30px);} to{opacity:1; transform:translateX(0);}}\n.toast .t-ico{font-size:18px;}\n.toast b{display:block; font-size:12.5px;}\n.toast span{color:var(--text-dim); font-size:11.5px;}\n.toast.xp b{color:var(--orange);}\n.toast.ok .t-ico{color:var(--green);}\n.toast.err .t-ico{color:var(--red);}\n\n/* Console frame (signature motif) */\n.console-frame{\n  background:#0a0d12; border:1px solid #232b36; border-radius:12px; overflow:hidden;\n  box-shadow: var(--shadow);\n}\n[data-theme=\"light\"] .console-frame{background:#12161c;}\n.console-topbar{\n  display:flex; align-items:center; gap:8px; padding:9px 14px; background:#12161d; border-bottom:1px solid #232b36;\n}\n.console-dot{width:10px; height:10px; border-radius:50%;}\n.console-topbar .url{\n  margin-left:10px; flex:1; background:#0d1117; border:1px solid #232b36; border-radius:7px; padding:4px 10px;\n  font-family:var(--mono); font-size:11px; color:#7d8b9c;\n}\n.console-body{display:flex; min-height:280px;}\n.console-nav{width:170px; flex-shrink:0; border-right:1px solid #1c232d; padding:10px 6px; background:#0d1117;}\n.console-nav-item{\n  padding:9px 10px; font-size:12px; color:#8b98a8; border-radius:7px; margin-bottom:2px; display:flex; align-items:center; gap:8px;\n  transition:.15s; cursor:pointer;\n}\n.console-nav-item:hover{background:#171e28; color:#e6ebf1;}\n.console-nav-item.active{background:rgba(255,59,48,.15); color:#ff6b60; font-weight:600;}\n.console-content{flex:1; padding:18px 20px; color:#c9d2dc; font-size:13px;}\n.console-content h3{color:#fff; font-size:16px; margin-bottom:8px;}\n.console-content p{color:#93a1b2; line-height:1.6; margin-bottom:10px; font-size:12.5px;}\n\n/* Mission Map */\n.mission-map{position:relative; padding:30px 10px;}\n.mission-track{\n  display:flex; flex-wrap:wrap; gap:20px; position:relative;\n}\n.m-node{\n  width:220px; background:var(--panel); border:1px solid var(--border); border-radius:16px; padding:18px;\n  position:relative; transition:.2s; cursor:pointer;\n}\n.m-node:hover{transform:translateY(-3px); border-color:var(--text-faint);}\n.m-node.locked{opacity:.45; cursor:not-allowed; filter:grayscale(.6);}\n.m-node.locked:hover{transform:none;}\n.m-node.done{border-color:var(--green-dim); background:linear-gradient(180deg, rgba(61,220,132,.06), var(--panel));}\n.m-node.current{border-color:var(--red-dim); box-shadow:0 0 0 3px var(--red-glow);}\n.m-num{\n  width:34px; height:34px; border-radius:10px; background:var(--panel2); border:1px solid var(--border);\n  display:flex; align-items:center; justify-content:center; font-weight:800; font-size:13px; margin-bottom:10px;\n}\n.m-node.done .m-num{background:var(--green); color:#052e17; border-color:var(--green);}\n.m-node.current .m-num{background:var(--red); color:#fff; border-color:var(--red);}\n.m-node h4{font-size:14.5px; margin-bottom:4px;}\n.m-node p{font-size:11.5px; color:var(--text-dim); line-height:1.5; margin-bottom:10px;}\n.m-node .m-xp{font-size:11px; color:var(--orange); font-weight:700;}\n\n/* Drag & Drop */\n.dropzone{\n  min-height:110px; border:2px dashed var(--border); border-radius:12px; padding:12px; display:flex; flex-wrap:wrap; gap:8px;\n  align-content:flex-start; transition:.15s; background:var(--panel2);\n}\n.dropzone.over{border-color:var(--blue); background:rgba(77,163,255,.06);}\n.dropzone.wrong{animation:shake .4s;}\n.dropzone.correct{border-color:var(--green); background:rgba(61,220,132,.06);}\n@keyframes shake{0%,100%{transform:translateX(0);}20%{transform:translateX(-8px);}40%{transform:translateX(8px);}60%{transform:translateX(-6px);}80%{transform:translateX(6px);}}\n.drag-chip{\n  padding:9px 14px; background:var(--panel); border:1px solid var(--border); border-radius:9px; font-size:12.5px; font-weight:600;\n  cursor:grab; user-select:none; display:flex; align-items:center; gap:6px;\n}\n.drag-chip:active{cursor:grabbing;}\n.drag-chip.placed{opacity:.35; pointer-events:none;}\n\n/* Forms */\n.field{margin-bottom:14px;}\n.field label{display:block; font-size:12px; color:var(--text-dim); margin-bottom:6px; font-weight:600;}\n.field input, .field select{\n  width:100%; padding:10px 12px; border-radius:9px; border:1px solid var(--border); background:var(--panel2);\n  color:var(--text); font-size:13px; font-family:inherit;\n}\n.field input:focus, .field select:focus{outline:none; border-color:var(--red-dim);}\n\n/* Terminal */\n.terminal{\n  background:#0a0d12; border-radius:12px; border:1px solid #232b36; font-family:var(--mono); font-size:12.5px;\n  padding:16px; min-height:260px; color:#3ddc84; overflow-y:auto; max-height:400px;\n}\n.terminal .line{margin-bottom:6px; line-height:1.6;}\n.terminal .prompt{color:#4da3ff;}\n.terminal .out{color:#c9d2dc;}\n.terminal .comment{color:#5f6b7a;}\n.term-input-row{display:flex; align-items:center; gap:6px; margin-top:4px;}\n.term-input-row input{\n  flex:1; background:transparent; border:none; color:#3ddc84; font-family:var(--mono); font-size:12.5px; outline:none;\n}\n.cursor-blink{width:7px; height:14px; background:#3ddc84; display:inline-block; animation:blink 1s infinite;}\n@keyframes blink{50%{opacity:0;}}\n\n/* Policy editor */\n.policy-editor{\n  background:#0a0d12; border-radius:12px; border:1px solid #232b36; font-family:var(--mono); font-size:13px;\n  padding:16px; color:#c9d2dc; min-height:120px; line-height:1.9;\n}\n.tok-allow{color:#ff6b60; font-weight:700;}\n.tok-group{color:#4da3ff;}\n.tok-verb{color:#ffd54a; font-weight:700;}\n.tok-resource{color:#3ddc84;}\n.tok-scope{color:#b48bff; font-weight:700;}\n.tok-name{color:#ffab40;}\n\n/* Quiz */\n.quiz-q{margin-bottom:22px; padding-bottom:18px; border-bottom:1px solid var(--border-soft);}\n.quiz-q:last-child{border:none;}\n.quiz-q .q-txt{font-weight:700; font-size:14px; margin-bottom:12px;}\n.q-opt{\n  display:flex; align-items:center; gap:10px; padding:11px 14px; border:1px solid var(--border); border-radius:10px;\n  margin-bottom:8px; cursor:pointer; transition:.15s; font-size:13px;\n}\n.q-opt:hover{border-color:var(--text-faint);}\n.q-opt.selected{border-color:var(--blue-dim); background:rgba(77,163,255,.08);}\n.q-opt.correct{border-color:var(--green-dim); background:rgba(61,220,132,.1);}\n.q-opt.incorrect{border-color:var(--red-dim); background:rgba(255,59,48,.1);}\n.q-explain{\n  margin-top:8px; padding:10px 12px; background:var(--panel2); border-radius:9px; font-size:12px; color:var(--text-dim);\n  display:none; border-left:3px solid var(--blue-dim);\n}\n.q-explain.show{display:block;}\n\n/* Achievements */\n.ach-card{\n  text-align:center; padding:22px 14px; border-radius:14px; border:1px solid var(--border); background:var(--panel);\n  transition:.2s;\n}\n.ach-card.locked{opacity:.35; filter:grayscale(1);}\n.ach-card .ico{font-size:34px; margin-bottom:10px;}\n.ach-card h5{font-size:13px; margin-bottom:4px;}\n.ach-card p{font-size:11px; color:var(--text-dim);}\n\n/* Globe / regions */\n.region-grid{display:grid; grid-template-columns:repeat(auto-fill,minmax(150px,1fr)); gap:12px;}\n.region-card{\n  padding:14px; border-radius:12px; border:1px solid var(--border); background:var(--panel); cursor:pointer; transition:.15s;\n  position:relative;\n}\n.region-card:hover{border-color:var(--blue-dim); transform:translateY(-2px);}\n.region-card.home{border-color:var(--red-dim); background:linear-gradient(180deg, var(--red-glow), var(--panel));}\n.region-card .flag{font-size:20px; margin-bottom:6px;}\n.region-card h5{font-size:12.5px;}\n.region-card small{color:var(--text-faint); font-size:10.5px;}\n\n/* AD / FD */\n.dc-row{display:flex; gap:18px; flex-wrap:wrap;}\n.dc-building{\n  flex:1; min-width:150px; background:var(--panel); border:1px solid var(--border); border-radius:14px; padding:18px; text-align:center;\n  cursor:pointer; transition:.2s; position:relative;\n}\n.dc-building:hover{border-color:var(--blue-dim);}\n.dc-building.failed{border-color:var(--red-dim); background:rgba(255,59,48,.06);}\n.dc-building .ico{font-size:30px; margin-bottom:8px;}\n.dc-building.active-glow{box-shadow:0 0 0 3px rgba(61,220,132,.25); border-color:var(--green-dim);}\n\n/* Relationship graph */\n.rgraph{display:flex; align-items:center; justify-content:center; gap:0; flex-wrap:wrap; padding:20px 0;}\n.rg-col{display:flex; flex-direction:column; gap:12px; align-items:center;}\n.rg-node{\n  padding:10px 16px; border-radius:10px; border:1px solid var(--border); background:var(--panel2); font-size:12px; font-weight:600;\n  white-space:nowrap;\n}\n.rg-arrow{color:var(--text-faint); font-size:20px; padding:0 18px;}\n\n/* misc */\n.kbd{font-family:var(--mono); background:var(--panel2); border:1px solid var(--border); padding:1px 6px; border-radius:5px; font-size:11px;}\n.hr{height:1px; background:var(--border-soft); margin:20px 0;}\n.two-col{display:grid; grid-template-columns:1fr 1fr; gap:18px;}\n@media(max-width:900px){.two-col{grid-template-columns:1fr;} .sidebar{display:none;}}\n.tag-list{display:flex; flex-wrap:wrap; gap:8px;}\n.info-box{padding:12px 14px; border-radius:10px; border-left:3px solid var(--blue-dim); background:rgba(77,163,255,.06); font-size:12.5px; margin:12px 0;}\n.tip-box{padding:12px 14px; border-radius:10px; border-left:3px solid var(--orange); background:rgba(255,171,64,.07); font-size:12.5px; margin:12px 0;}\n.mistake-box{padding:12px 14px; border-radius:10px; border-left:3px solid var(--red); background:rgba(255,59,48,.06); font-size:12.5px; margin:12px 0;}\n.hidden{display:none !important;}\n\n", "html": "\n\n<div id=\"toast-wrap\"></div>\n\n<!-- TOP BAR -->\n<div class=\"topbar\">\n  <div class=\"brand\"><div class=\"logo\">C</div><div>OCI IAM Lab <small>1Z0-1067-26 \u00b7 Day 1</small></div></div>\n  <div class=\"crumb\">Home <span>\u203a</span> <b id=\"crumbCurrent\">Mission Control</b></div>\n  <div class=\"topbar-right\">\n    <div class=\"xp-chip\"><span class=\"dot\"></span><span id=\"xpDisplay\">0</span> XP</div>\n    <div class=\"rank-chip\" id=\"rankChip\">Recruit</div>\n    <button class=\"icon-btn\" id=\"themeToggle\" title=\"Toggle theme\">\u25d0</button>\n  </div>\n</div>\n\n<div class=\"app\">\n  <!-- SIDEBAR -->\n  <div class=\"sidebar\" id=\"sidebar\"></div>\n\n  <!-- MAIN -->\n  <div class=\"main\" id=\"main\"></div>\n</div>\n\n\n", "js": "\n/* ================= DATA ================= */\n\nconst NAV = [\n  {id:'home', label:'Mission Control', ico:'\u2302', group:'main'},\n  {id:'missionmap', label:'Mission Map', ico:'\ud83d\uddfa', group:'main'},\n  {id:'console', label:'OCI Console Explorer', ico:'\u2601', group:'explore'},\n  {id:'regions', label:'Regions Explorer', ico:'\ud83c\udf10', group:'explore'},\n  {id:'ad', label:'Availability Domains', ico:'\ud83c\udfe2', group:'explore'},\n  {id:'fd', label:'Fault Domains', ico:'\u26a1', group:'explore'},\n  {id:'m1', label:'M1 \u00b7 Create Account', ico:'\u2460', group:'missions'},\n  {id:'m2', label:'M2 \u00b7 Compartments', ico:'\u2461', group:'missions'},\n  {id:'m3', label:'M3 \u00b7 Create Users', ico:'\u2462', group:'missions'},\n  {id:'m4', label:'M4 \u00b7 Groups', ico:'\u2463', group:'missions'},\n  {id:'m5', label:'M5 \u00b7 Assign Users', ico:'\u2464', group:'missions'},\n  {id:'m6', label:'M6 \u00b7 Policy Builder', ico:'\u2465', group:'missions'},\n  {id:'m7', label:'M7 \u00b7 Policy Simulator', ico:'\u2466', group:'missions'},\n  {id:'m8', label:'M8 \u00b7 OCI CLI', ico:'\u2467', group:'missions'},\n  {id:'cliconfig', label:'CLI Config Simulator', ico:'\u2318', group:'extra'},\n  {id:'challenges', label:'Real-World Challenges', ico:'\ud83e\udde9', group:'extra'},\n  {id:'achievements', label:'Achievements', ico:'\ud83c\udfc6', group:'extra'},\n  {id:'dashboard', label:'Dashboard', ico:'\ud83d\udcca', group:'extra'},\n  {id:'capstone', label:'Final Capstone', ico:'\ud83c\udf93', group:'extra'},\n];\n\nconst MISSIONS = [\n  {id:'m1', num:1, title:'Create OCI Account', desc:'Simulate signing up for OCI Free Tier.', xp:100},\n  {id:'m2', num:2, title:'Create Compartments', desc:'Build the Dev / Test / Prod hierarchy.', xp:120},\n  {id:'m3', num:3, title:'Create Users', desc:'Provision AdminUser, DevUser, Auditor.', xp:120},\n  {id:'m4', num:4, title:'Create Groups', desc:'Administrators, Developers, Auditors.', xp:100},\n  {id:'m5', num:5, title:'Assign Users to Groups', desc:'Drag-and-drop assignment challenge.', xp:130},\n  {id:'m6', num:6, title:'IAM Policy Builder', desc:'Write real OCI policy statements.', xp:150},\n  {id:'m7', num:7, title:'Policy Simulator', desc:'Test who can do what, and why.', xp:150},\n  {id:'m8', num:8, title:'OCI CLI', desc:'Run identity commands in Cloud Shell.', xp:130},\n];\n\nconst REGIONS = [\n  {code:'us-ashburn-1', name:'US East (Ashburn)', flag:'\ud83c\uddfa\ud83c\uddf8', lat:14, home:true, ads:3},\n  {code:'us-phoenix-1', name:'US West (Phoenix)', flag:'\ud83c\uddfa\ud83c\uddf8', lat:22, home:false, ads:3},\n  {code:'uk-london-1', name:'UK South (London)', flag:'\ud83c\uddec\ud83c\udde7', lat:96, home:false, ads:1},\n  {code:'eu-frankfurt-1', name:'Germany Central (Frankfurt)', flag:'\ud83c\udde9\ud83c\uddea', lat:88, home:false, ads:1},\n  {code:'ap-mumbai-1', name:'India West (Mumbai)', flag:'\ud83c\uddee\ud83c\uddf3', lat:170, home:false, ads:1},\n  {code:'ap-tokyo-1', name:'Japan East (Tokyo)', flag:'\ud83c\uddef\ud83c\uddf5', lat:150, home:false, ads:1},\n  {code:'ap-sydney-1', name:'Australia East (Sydney)', flag:'\ud83c\udde6\ud83c\uddfa', lat:120, home:false, ads:1},\n  {code:'sa-saopaulo-1', name:'Brazil East (Sao Paulo)', flag:'\ud83c\udde7\ud83c\uddf7', lat:60, home:false, ads:1},\n];\n\nconst CONSOLE_MENUS = {\n  Compute:{ico:'\ud83d\udda5', text:'Create and manage virtual machines (Instances), bare metal hosts, and Instance Pools/Autoscaling. Compute resources always live inside a Compartment and a VCN subnet.'},\n  Networking:{ico:'\ud83c\udf10', text:'Virtual Cloud Networks (VCNs), subnets, route tables, security lists, load balancers, and gateways. Networking is the backbone every other service depends on.'},\n  Storage:{ico:'\ud83d\udcbe', text:'Block Volumes, Object Storage buckets, File Storage, and Archive Storage. IAM policies control who can read/write which buckets and volumes.'},\n  Identity:{ico:'\ud83d\udd11', text:'The IAM service itself \u2014 Users, Groups, Dynamic Groups, Compartments, Policies, Identity Domains, and Federation. This is what today\\'s lab focuses on.'},\n  Governance:{ico:'\ud83d\udccb', text:'Tagging, Budgets, Cost Analysis, Cloud Guard, and Audit. Governance tools let administrators enforce policy and track spend across compartments.'},\n  'Developer Services':{ico:'\u2699', text:'OCI Resource Manager (Terraform), DevOps pipelines, Container Registry, Functions, and API Gateway.'},\n  Monitoring:{ico:'\ud83d\udcc8', text:'Metrics, Alarms, Notifications, and Logging. Used to observe IAM sign-in events and policy evaluation failures.'},\n};\n\nconst QUIZZES = {\n  m1:[\n    {q:'What is required to activate an OCI Free Tier account?', opts:['Email + phone + credit card verification','Only an email address','A GitHub account','A government ID upload'], a:0, ex:'Oracle verifies identity via email, SMS/phone, and a card for fraud prevention (no charge unless you upgrade).'},\n    {q:'What do you get automatically with OCI Free Tier?', opts:['Always Free resources + 30-day trial credits','Unlimited compute forever','Only object storage','Nothing until you pay'], a:0, ex:'Free Tier combines Always Free eligible services with time-limited trial credits.'},\n    {q:'Which region is assigned as your Home Region at signup?', opts:['The one you pick during account creation','Always us-ashburn-1','A random region','Whichever is cheapest'], a:0, ex:'You choose your Home Region during signup and it cannot be changed later \u2014 it hosts your IAM resources.'},\n  ],\n  m2:[\n    {q:'What is the top-level container in every OCI tenancy?', opts:['Root Compartment','Default VCN','Admin Group','Home Region'], a:0, ex:'Every tenancy starts with a Root Compartment; all other compartments nest beneath it.'},\n    {q:'Why do enterprises separate Dev/Test/Prod into compartments?', opts:['Isolate resources, billing, and access boundaries','Compartments are required for networking','To reduce region latency','Compartments increase compute quota'], a:0, ex:'Compartments are logical boundaries for access control, cost tracking, and resource organization \u2014 not physical/network boundaries.'},\n    {q:'Can a compartment be nested inside another compartment?', opts:['Yes, up to six levels deep','No, only one level is allowed','Only in Free Tier','Only Production can be nested'], a:0, ex:'OCI supports compartment nesting up to six levels beneath the root.'},\n  ],\n  m3:[\n    {q:'What OCI IAM entity represents an individual person or application needing access?', opts:['User','Group','Policy','Compartment'], a:0, ex:'A User is an individual identity (person or service) that authenticates to OCI.'},\n    {q:'How should permissions typically be granted to a user?', opts:['Indirectly, via group membership','Directly attached to the user only','Via the compartment name','Through the tenancy OCID'], a:0, ex:'Best practice is never to write policies against individual users \u2014 always grant access through groups.'},\n    {q:'What happens the first time a local IAM user\\'s credentials are generated?', opts:['A one-time password/API key must be securely downloaded','The password is emailed automatically','No credentials are needed','The user auto-joins Administrators'], a:0, ex:'OCI shows the generated password/API key once \u2014 it must be captured and stored securely at creation time.'},\n  ],\n  m4:[\n    {q:'What is the primary benefit of using Groups in IAM?', opts:['Simplifies permission management at scale','Groups increase compute performance','Groups replace compartments','Groups are required for networking'], a:0, ex:'Groups let you manage permissions once at the group level instead of per-user, which scales far better.'},\n    {q:'Can a user belong to more than one group?', opts:['Yes, a user can belong to multiple groups','No, only one group per user','Only Administrators can join multiple groups','Groups are mutually exclusive'], a:0, ex:'Users can be members of multiple groups, and their effective permissions are the union of all attached policies.'},\n    {q:'Which group typically receives \"manage all-resources in tenancy\"?', opts:['Administrators','Auditors','Developers','Guests'], a:0, ex:'The Administrators group is generally the only one granted full tenancy-wide manage rights.'},\n  ],\n  m5:[\n    {q:'What determines what a user can actually do in OCI?', opts:['The policies attached to the groups they belong to','The user\\'s display name','The compartment they were created in','Their sign-in time'], a:0, ex:'Effective access = union of all policy statements referencing any group the user is a member of.'},\n    {q:'If DevUser is mistakenly added to Administrators, what happens?', opts:['DevUser inherits full tenancy admin rights','Nothing changes until re-login','Only compute access is affected','OCI blocks the assignment automatically'], a:0, ex:'Group membership immediately grants whatever the group\\'s policies allow \u2014 over-provisioning group membership is a common real-world security mistake.'},\n  ],\n  m6:[\n    {q:'What is the correct basic structure of an OCI policy statement?', opts:['Allow <subject> to <verb> <resource-type> in <location>','Grant <resource> to <user> at <region>','Policy <group> = <permission>','IAM(<user>,<resource>,<action>)'], a:0, ex:'OCI policies read like English: Allow group X to manage instance-family in compartment Y.'},\n    {q:'Which verb grants the LEAST access?', opts:['inspect','read','use','manage'], a:0, ex:'Verb hierarchy from least to most access: inspect < read < use < manage.'},\n    {q:'What does \"all-resources\" refer to in a policy?', opts:['Every resource type OCI offers','Only compute instances','Only IAM resources','Only storage buckets'], a:0, ex:'all-resources is a broad aggregate resource-type covering everything in the target compartment/tenancy.'},\n  ],\n  m7:[\n    {q:'If no policy grants an action, what is the default result?', opts:['Denied \u2014 OCI IAM defaults to deny','Allowed \u2014 OCI IAM defaults to allow','It depends on the region','It depends on the compartment name'], a:0, ex:'OCI IAM is deny-by-default: without an explicit Allow statement, access is denied.'},\n    {q:'Auditor has \"inspect all-resources in tenancy\". Can Auditor delete a bucket?', opts:['No \u2014 inspect only allows viewing metadata, not deleting','Yes, inspect includes delete','Only if the bucket is empty','Only on weekdays'], a:0, ex:'inspect is the lowest verb \u2014 list/metadata only. Deleting requires at least manage (or use, for some resource types).'},\n  ],\n  m8:[\n    {q:'Which CLI command lists IAM users in the tenancy?', opts:['oci iam user list','oci user get-all','oci identity users','oci list users'], a:0, ex:'The OCI CLI follows the pattern: oci <service> <resource> <action> \u2014 so \"oci iam user list\".'},\n    {q:'What must you run once before using the OCI CLI?', opts:['oci setup config','oci login','oci init','oci --activate'], a:0, ex:'\"oci setup config\" walks you through generating the ~/.oci/config file with your keys and tenancy details.'},\n  ],\n};\n\nconst CHALLENGES = [\n  {id:'c1', title:'Developer cannot create a VM', scenario:'DevUser reports \"Authorization failed\" when launching a Compute instance in the Development compartment.', opts:['The Developers group is missing a policy granting manage instance-family in compartment Development','The VCN is in the wrong region','DevUser forgot their password','The compartment has too many tags'], a:0, ex:'Without an explicit manage instance-family (or all-resources) statement scoped to Development, OCI denies the action by default.'},\n  {id:'c2', title:'Auditor deletes a bucket \u2014 then it\\'s denied', scenario:'The Auditor account is told to delete an old Object Storage bucket but the console shows \"Not Authorized\".', opts:['Auditors only have \"inspect\", which cannot delete anything','Auditors have a corrupted password','The bucket is in a locked region','Buckets can never be deleted by anyone'], a:0, ex:'This is by design \u2014 Auditors are read-only. Deleting requires elevated verbs like manage.'},\n  {id:'c3', title:'Wrong compartment selected', scenario:'A learner creates a Compute instance but can\\'t find it later \u2014 it doesn\\'t appear under the Production compartment.', opts:['The console compartment selector was left on a different compartment during creation','The instance was deleted automatically','OCI hides new instances for 24 hours','The instance was created in another tenancy'], a:0, ex:'OCI console always scopes list views to the compartment selected in the left filter \u2014 a very common real-world mistake.'},\n  {id:'c4', title:'Policy typo', scenario:'A policy reads: \"Alow group Developers to manage instance-family in compartment Development\" and grants nothing.', opts:['\"Alow\" is misspelled \u2014 it must be exactly \"Allow\"','The compartment name needs quotes','Groups can\\'t be named Developers','Policies must be all lowercase'], a:0, ex:'OCI policy statements require exact keyword syntax; a misspelled verb/keyword causes the whole statement to fail validation.'},\n  {id:'c5', title:'CLI Authentication Failed', scenario:'Running \"oci iam user list\" returns \"NotAuthenticated \u2014 The required information to complete authentication was not provided\".', opts:['The ~/.oci/config file has a missing/incorrect key fingerprint or private key path','The internet connection is down','The CLI needs to be reinstalled','The tenancy has no users yet'], a:0, ex:'Most CLI auth failures trace back to config file fields: user OCID, tenancy OCID, fingerprint, key_file path, or region being wrong or mismatched with the uploaded public key.'},\n];\n\nconst ACHIEVEMENTS = [\n  {id:'a1', name:'First Login', ico:'\ud83d\udd11', cond:'Complete Mission 1', check:s=>s.done.has('m1')},\n  {id:'a2', name:'IAM Architect', ico:'\ud83c\udfdb', cond:'Complete Missions 2\u20135', check:s=>['m2','m3','m4','m5'].every(m=>s.done.has(m))},\n  {id:'a3', name:'Policy Master', ico:'\ud83d\udcdc', cond:'Complete Mission 6 with a perfect quiz', check:s=>s.done.has('m6') && (s.quizScores.m6||0)>=3},\n  {id:'a4', name:'CLI Explorer', ico:'\ud83d\udcbb', cond:'Complete Mission 8', check:s=>s.done.has('m8')},\n  {id:'a5', name:'Security Expert', ico:'\ud83d\udee1', cond:'Solve all 5 real-world challenges', check:s=>s.challengesDone.size>=5},\n];\n\nconst CLI_STEPS = [\n  {cmd:'oci --version', out:'3.45.2', note:'Confirms the CLI is installed and shows the current version.'},\n  {cmd:'oci setup config', out:'Config written to /home/user/.oci/config\\nDone.', note:'Interactive wizard: prompts for tenancy OCID, user OCID, region, and generates an API signing key pair.'},\n  {cmd:'oci iam user list', out:'{\\n  \"data\": [\\n    {\"name\":\"AdminUser\",\"lifecycle-state\":\"ACTIVE\"},\\n    {\"name\":\"DevUser\",\"lifecycle-state\":\"ACTIVE\"},\\n    {\"name\":\"Auditor\",\"lifecycle-state\":\"ACTIVE\"}\\n  ]\\n}', note:'Lists every IAM user visible in the tenancy as JSON.'},\n  {cmd:'oci iam group list', out:'{\\n  \"data\": [\\n    {\"name\":\"Administrators\"},\\n    {\"name\":\"Developers\"},\\n    {\"name\":\"Auditors\"}\\n  ]\\n}', note:'Lists all IAM groups.'},\n  {cmd:'oci iam compartment list', out:'{\\n  \"data\": [\\n    {\"name\":\"Development\",\"lifecycle-state\":\"ACTIVE\"},\\n    {\"name\":\"Testing\",\"lifecycle-state\":\"ACTIVE\"},\\n    {\"name\":\"Production\",\"lifecycle-state\":\"ACTIVE\"}\\n  ]\\n}', note:'Lists compartments visible from the root.'},\n];\n\n\n/* ================= STATE ================= */\nconst STATE = {\n  view:'home',\n  xp:0,\n  done:new Set(),\n  quizScores:{},\n  quizAnswered:{},\n  challengesDone:new Set(),\n  theme:'dark',\n  selectedChip:null,\n  m2:{placed:{}},          // compartment name -> true if correctly placed\n  m3:{created:{}},         // username -> {email}\n  m4:{created:{}},         // group name -> true\n  m5:{assigned:{}},        // user -> group placed\n  m6:{written:{}},         // statement index -> true\n  m7:{role:'AdminUser', tested:{}},\n  m8:{step:0, history:[]},\n  cliConfigStep:0,\n  cliConfigDone:false,\n  achUnlocked:new Set(),\n};\n\nconst MISSION_ORDER = ['m1','m2','m3','m4','m5','m6','m7','m8'];\n\nfunction isUnlocked(id){\n  const idx = MISSION_ORDER.indexOf(id);\n  if(idx<=0) return true;\n  return STATE.done.has(MISSION_ORDER[idx-1]);\n}\n\nfunction rankFor(xp){\n  if(xp>=1000) return 'OCI IAM Expert';\n  if(xp>=700) return 'Security Architect';\n  if(xp>=400) return 'Cloud Engineer';\n  if(xp>=150) return 'Associate';\n  return 'Recruit';\n}\n\nfunction addXP(n, label){\n  STATE.xp += n;\n  document.getElementById('xpDisplay').textContent = STATE.xp;\n  document.getElementById('rankChip').textContent = rankFor(STATE.xp);\n  toast('xp', `+${n} XP`, label||'Nice work!');\n  checkAchievements();\n}\n\nfunction toast(type, title, msg){\n  const wrap = document.getElementById('toast-wrap');\n  const el = document.createElement('div');\n  el.className = 'toast ' + type;\n  const ico = type==='xp' ? '\u2b50' : type==='ok' ? '\u2705' : type==='err' ? '\u26d4' : '\u2139';\n  el.innerHTML = `<div class=\"t-ico\">${ico}</div><div><b>${title}</b><span>${msg||''}</span></div>`;\n  wrap.appendChild(el);\n  setTimeout(()=>{ el.style.transition='opacity .4s'; el.style.opacity='0'; setTimeout(()=>el.remove(),400); }, 3200);\n}\n\nfunction completeMission(id, xp){\n  if(STATE.done.has(id)) return;\n  STATE.done.add(id);\n  addXP(xp, MISSIONS.find(m=>m.id===id).title + ' complete');\n  toast('ok','Mission Complete', MISSIONS.find(m=>m.id===id).title);\n  renderSidebar();\n  const idx = MISSION_ORDER.indexOf(id);\n  if(idx>=0 && idx<MISSION_ORDER.length-1){\n    setTimeout(()=>toast('info','Next mission unlocked', MISSIONS[idx+1].title), 900);\n  }\n}\n\nfunction checkAchievements(){\n  ACHIEVEMENTS.forEach(a=>{\n    if(!STATE.achUnlocked.has(a.id) && a.check(STATE)){\n      STATE.achUnlocked.add(a.id);\n      setTimeout(()=>toast('ok','Achievement Unlocked \ud83c\udfc6', a.name), 600);\n    }\n  });\n}\n\n/* ================= NAV / SIDEBAR ================= */\nfunction renderSidebar(){\n  const groups = {main:'Overview', explore:'Explore OCI', missions:'Mission Track', extra:'Beyond the Labs'};\n  let html = '';\n  Object.keys(groups).forEach(g=>{\n    html += `<h4>${groups[g]}</h4>`;\n    NAV.filter(n=>n.group===g).forEach(n=>{\n      let locked = false, done = false;\n      if(MISSION_ORDER.includes(n.id)){\n        locked = !isUnlocked(n.id);\n        done = STATE.done.has(n.id);\n      }\n      html += `<div class=\"nav-item ${STATE.view===n.id?'active':''} ${locked?'locked':''} ${done?'done':''}\"\n        onclick=\"${locked?'':`setView('${n.id}')`}\">\n        <span class=\"n-ico\">${done?'\u2713':n.ico}</span>${n.label}\n        ${locked?'<span class=\\\"nav-badge\\\">\ud83d\udd12</span>':''}\n      </div>`;\n    });\n  });\n  const pct = Math.round((STATE.done.size/MISSION_ORDER.length)*100);\n  html += `<div class=\"progress-mini\">\n    <div class=\"lbl\"><span>Mission Progress</span><span>${pct}%</span></div>\n    <div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:${pct}%\"></div></div>\n  </div>`;\n  document.getElementById('sidebar').innerHTML = html;\n}\n\nfunction setView(id){\n  STATE.view = id;\n  const nav = NAV.find(n=>n.id===id);\n  document.getElementById('crumbCurrent').textContent = nav ? nav.label : id;\n  renderSidebar();\n  renderMain();\n  const mainEl = document.getElementById('main');\n  if(mainEl.scrollIntoView) mainEl.scrollIntoView({behavior:'smooth', block:'start'});\n}\n\nfunction renderMain(){\n  const map = {\n    home:renderHome, missionmap:renderMissionMap, console:renderConsoleView,\n    regions:renderRegions, ad:renderAD, fd:renderFD,\n    m1:renderM1, m2:renderM2, m3:renderM3, m4:renderM4, m5:renderM5, m6:renderM6, m7:renderM7, m8:renderM8,\n    cliconfig:renderCliConfig, challenges:renderChallenges, achievements:renderAchievements,\n    dashboard:renderDashboard, capstone:renderCapstone,\n  };\n  const fn = map[STATE.view] || renderHome;\n  document.getElementById('main').innerHTML = `<div class=\"view active\">${fn()}</div>`;\n  afterRenderHooks[STATE.view] && afterRenderHooks[STATE.view]();\n}\n\nconst afterRenderHooks = {};\n\n/* ================= HOME ================= */\nfunction renderHome(){\n  const pct = Math.round((STATE.done.size/MISSION_ORDER.length)*100);\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Oracle Cloud Infrastructure Operations Professional \u00b7 1Z0-1067-26</div>\n    <h1 class=\"page-title\">Day 1 Lab \u2014 OCI Identity &amp; Access Management</h1>\n    <p class=\"page-sub\">Mission: Build a complete enterprise identity architecture \u2014 compartments, users, groups, policies, and CLI access \u2014 exactly like you would inside a real OCI tenancy.</p>\n  </div>\n  <div class=\"grid grid-4\" style=\"margin-bottom:18px;\">\n    <div class=\"card\"><div class=\"pill pill-orange\">XP</div><h2 style=\"margin-top:10px;font-size:26px;\">${STATE.xp}</h2><p class=\"page-sub\" style=\"margin-top:2px;\">Total experience</p></div>\n    <div class=\"card\"><div class=\"pill pill-blue\">Rank</div><h2 style=\"margin-top:10px;font-size:20px;\">${rankFor(STATE.xp)}</h2><p class=\"page-sub\" style=\"margin-top:2px;\">Current standing</p></div>\n    <div class=\"card\"><div class=\"pill pill-green\">Missions</div><h2 style=\"margin-top:10px;font-size:26px;\">${STATE.done.size}/8</h2><p class=\"page-sub\" style=\"margin-top:2px;\">Completed</p></div>\n    <div class=\"card\"><div class=\"pill pill-red\">Completion</div><h2 style=\"margin-top:10px;font-size:26px;\">${pct}%</h2><div class=\"bar-track\" style=\"margin-top:8px;\"><div class=\"bar-fill\" style=\"width:${pct}%\"></div></div></div>\n  </div>\n  <div class=\"card\" style=\"text-align:center; padding:44px 24px; background:linear-gradient(180deg, var(--red-glow), var(--panel));\">\n    <div style=\"font-size:13px; color:var(--text-dim); letter-spacing:1px; text-transform:uppercase; margin-bottom:10px;\">Current Lab</div>\n    <h2 style=\"font-size:22px; margin-bottom:10px;\">${STATE.done.size===0 ? 'Mission 1 \u2014 Create OCI Account' : (MISSION_ORDER[STATE.done.size] ? 'Mission '+(STATE.done.size+1)+' \u2014 '+MISSIONS[STATE.done.size].title : 'All Missions Complete!')}</div>\n    <p class=\"page-sub\" style=\"margin:0 auto 20px; text-align:center;\">Estimated time remaining: ${(8-STATE.done.size)*8} minutes</p>\n    <button class=\"btn btn-primary\" onclick=\"setView('missionmap')\">\ud83d\ude80 Start Mission</button>\n  </div>\n  <div class=\"hr\"></div>\n  <h3 style=\"margin-bottom:12px; font-size:15px;\">Explore before you build</h3>\n  <div class=\"grid grid-3\">\n    <div class=\"card\" style=\"cursor:pointer;\" onclick=\"setView('console')\"><div style=\"font-size:22px;margin-bottom:8px;\">\u2601</div><h4 style=\"font-size:14px;\">OCI Console Explorer</h4><p class=\"page-sub\" style=\"margin-top:6px;\">Click through the real console navigation.</p></div>\n    <div class=\"card\" style=\"cursor:pointer;\" onclick=\"setView('regions')\"><div style=\"font-size:22px;margin-bottom:8px;\">\ud83c\udf10</div><h4 style=\"font-size:14px;\">Regions Explorer</h4><p class=\"page-sub\" style=\"margin-top:6px;\">Understand Home Region and latency.</p></div>\n    <div class=\"card\" style=\"cursor:pointer;\" onclick=\"setView('ad')\"><div style=\"font-size:22px;margin-bottom:8px;\">\ud83c\udfe2</div><h4 style=\"font-size:14px;\">Availability Domains</h4><p class=\"page-sub\" style=\"margin-top:6px;\">See fault-tolerant data center design.</p></div>\n  </div>`;\n}\n\n/* ================= MISSION MAP ================= */\nfunction renderMissionMap(){\n  let nodes = MISSIONS.map(m=>{\n    const locked = !isUnlocked(m.id);\n    const done = STATE.done.has(m.id);\n    const current = !locked && !done;\n    return `<div class=\"m-node ${locked?'locked':''} ${done?'done':''} ${current?'current':''}\" onclick=\"${locked?'':`setView('${m.id}')`}\">\n      <div class=\"m-num\">${done?'\u2713':m.num}</div>\n      <h4>${m.title}</h4>\n      <p>${m.desc}</p>\n      <div class=\"m-xp\">\u2b50 ${m.xp} XP</div>\n      ${locked?'<div class=\"pill pill-gray\" style=\"margin-top:8px;\">\ud83d\udd12 Locked</div>':''}\n    </div>`;\n  }).join('');\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Mission Map</div>\n    <h1 class=\"page-title\">Choose Your Mission</h1>\n    <p class=\"page-sub\">Each mission unlocks the next. Complete them in order to build a full enterprise IAM architecture.</p>\n  </div>\n  <div class=\"mission-map\"><div class=\"mission-track\">${nodes}</div></div>`;\n}\n\n/* ================= CONSOLE EXPLORER ================= */\nfunction renderConsoleView(){\n  const keys = Object.keys(CONSOLE_MENUS);\n  afterRenderHooks.console = ()=>selectConsoleMenu(keys[0]);\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Explore OCI Console</div>\n    <h1 class=\"page-title\">OCI Console Explorer</h1>\n    <p class=\"page-sub\">Click every menu on the left. This is exactly how the real Oracle Cloud console is organized.</p>\n  </div>\n  <div class=\"console-frame\">\n    <div class=\"console-topbar\"><span class=\"console-dot\" style=\"background:#ff5f57;\"></span><span class=\"console-dot\" style=\"background:#febc2e;\"></span><span class=\"console-dot\" style=\"background:#28c840;\"></span>\n      <div class=\"url\">console.oraclecloud.com/identity/domains</div></div>\n    <div class=\"console-body\">\n      <div class=\"console-nav\" id=\"consoleNav\">\n        ${keys.map(k=>`<div class=\"console-nav-item\" id=\"cnav-${k.replace(/\\s/g,'')}\" onclick=\"selectConsoleMenu('${k}')\">${CONSOLE_MENUS[k].ico} ${k}</div>`).join('')}\n      </div>\n      <div class=\"console-content\" id=\"consoleContent\"></div>\n    </div>\n  </div>\n  <div class=\"info-box\" style=\"margin-top:16px;\">\ud83d\udca1 Tip: The <b>Identity</b> menu is where every task in this lab happens \u2014 Users, Groups, Compartments, and Policies all live there.</div>`;\n}\nfunction selectConsoleMenu(k){\n  document.querySelectorAll('.console-nav-item').forEach(el=>el.classList.remove('active'));\n  const el = document.getElementById('cnav-'+k.replace(/\\s/g,'')); if(el) el.classList.add('active');\n  const info = CONSOLE_MENUS[k];\n  document.getElementById('consoleContent').innerHTML = `<h3>${info.ico} ${k}</h3><p>${info.text}</p>`;\n}\n\n/* ================= REGIONS ================= */\nfunction renderRegions(){\n  const cards = REGIONS.map(r=>`\n    <div class=\"region-card ${r.home?'home':''}\" onclick=\"selectRegion('${r.code}')\">\n      ${r.home?'<div class=\"pill pill-red\" style=\"position:absolute;top:10px;right:10px;\">HOME</div>':''}\n      <div class=\"flag\">${r.flag}</div><h5>${r.name}</h5><small>${r.code}</small>\n    </div>`).join('');\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Regions Explorer</div>\n    <h1 class=\"page-title\">Choose a Region, Understand Latency</h1>\n    <p class=\"page-sub\">Click a region to see details. Your Home Region is fixed at signup and is where core IAM resources are replicated from.</p>\n  </div>\n  <div class=\"region-grid\">${cards}</div>\n  <div class=\"card\" id=\"regionDetail\" style=\"margin-top:18px;\">Click a region above to see details.</div>\n  <div class=\"card\" style=\"margin-top:16px;\">\n    <div class=\"quiz-q\" style=\"margin-bottom:0;border:none;padding-bottom:0;\">\n      <div class=\"q-txt\">Quiz: Which region stores your core IAM resources?</div>\n      <div class=\"q-opt\" onclick=\"answerRegionQuiz(this,true)\">Your Home Region</div>\n      <div class=\"q-opt\" onclick=\"answerRegionQuiz(this,false)\">Whichever region has the lowest latency right now</div>\n      <div class=\"q-opt\" onclick=\"answerRegionQuiz(this,false)\">All regions equally, always in sync</div>\n      <div class=\"q-explain\" id=\"regionQuizExplain\">Correct \u2014 IAM (Users, Groups, Policies, Compartments) is defined once and is global, but administered from your Home Region.</div>\n    </div>\n  </div>`;\n}\nfunction selectRegion(code){\n  const r = REGIONS.find(x=>x.code===code);\n  document.getElementById('regionDetail').innerHTML = `\n    <h4 style=\"margin-bottom:8px;\">${r.flag} ${r.name}</h4>\n    <div class=\"tag-list\">\n      <span class=\"pill pill-blue\">Region: ${r.code}</span>\n      <span class=\"pill pill-orange\">Availability Domains: ${r.ads}</span>\n      <span class=\"pill ${r.home?'pill-red':'pill-gray'}\">${r.home?'Home Region':'Non-home Region'}</span>\n    </div>`;\n}\nfunction answerRegionQuiz(el, correct){\n  document.querySelectorAll('#main .q-opt').forEach(o=>o.classList.remove('selected'));\n  el.classList.add('selected');\n  const ex = document.getElementById('regionQuizExplain');\n  ex.classList.add('show');\n  if(correct) addXP(15,'Region quiz correct');\n}\n\n/* ================= AVAILABILITY DOMAINS ================= */\nfunction renderAD(){\n  const ads = [1,2,3];\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Explore OCI \u00b7 Fault Tolerance</div>\n    <h1 class=\"page-title\">Availability Domain Simulation</h1>\n    <p class=\"page-sub\">Click each data center. Each Availability Domain (AD) has independent power, cooling, and networking.</p>\n  </div>\n  <div class=\"dc-row\" id=\"adRow\">\n    ${ads.map(n=>`<div class=\"dc-building\" id=\"ad-${n}\" onclick=\"clickAD(${n})\"><div class=\"ico\">\ud83c\udfe2</div><h4>AD-${n}</h4><p class=\"page-sub\" style=\"margin-top:6px;\">Click to inspect</p></div>`).join('')}\n  </div>\n  <div class=\"card\" id=\"adDetail\" style=\"margin-top:16px;\">Click a building above.</div>\n  <div class=\"hr\"></div>\n  <button class=\"btn btn-ghost\" onclick=\"simulateFailover()\">\u25b6 Simulate Failover: AD-1 goes down</button>\n  <div id=\"failoverLog\" class=\"info-box hidden\" style=\"margin-top:14px;\"></div>`;\n}\nfunction clickAD(n){\n  document.getElementById('adDetail').innerHTML = `<h4>Availability Domain AD-${n}</h4>\n    <div class=\"tag-list\" style=\"margin-top:8px;\">\n      <span class=\"pill pill-green\">\u26a1 Independent power</span>\n      <span class=\"pill pill-blue\">\u2744 Independent cooling</span>\n      <span class=\"pill pill-orange\">\ud83d\udd0c Independent networking</span>\n    </div>\n    <p class=\"page-sub\" style=\"margin-top:10px;\">A failure in one AD is designed to never cascade into another AD within the same region.</p>`;\n}\nfunction simulateFailover(){\n  const ad1 = document.getElementById('ad-1');\n  ad1.classList.add('failed');\n  const ad2 = document.getElementById('ad-2');\n  ad2.classList.add('active-glow');\n  const log = document.getElementById('failoverLog');\n  log.classList.remove('hidden');\n  log.innerHTML = '\u26a0 AD-1 lost power. Workload automatically rerouted to AD-2 \u2014 application stayed online with zero data loss.';\n  addXP(20,'Failover simulation observed');\n  setTimeout(()=>{ ad1.classList.remove('failed'); ad2.classList.remove('active-glow'); }, 3500);\n}\n\n/* ================= FAULT DOMAINS ================= */\nfunction renderFD(){\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Explore OCI \u00b7 Fault Isolation</div>\n    <h1 class=\"page-title\">Fault Domain Simulation</h1>\n    <p class=\"page-sub\">Inside a single AD, Fault Domains (FDs) group hardware that doesn't share a single point of failure \u2014 like a rack.</p>\n  </div>\n  <div class=\"dc-row\" id=\"fdRow\">\n    ${[1,2,3].map(n=>`<div class=\"dc-building\" id=\"fd-${n}\"><div class=\"ico\">\ud83d\udda5</div><h4>FD-${n}</h4><p class=\"page-sub\" style=\"margin-top:6px;\" id=\"fd-${n}-label\">2 instances running</p></div>`).join('')}\n  </div>\n  <button class=\"btn btn-ghost\" style=\"margin-top:16px;\" onclick=\"simulateFDFailure()\">\u25b6 Simulate Hardware Failure in FD-1</button>\n  <div id=\"fdLog\" class=\"info-box hidden\" style=\"margin-top:14px;\"></div>\n  <div class=\"tip-box\" style=\"margin-top:16px;\">\ud83c\udf93 Exam tip: Spread instances across multiple Fault Domains (not just ADs) for HA within a single-AD region.</div>`;\n}\nfunction simulateFDFailure(){\n  document.getElementById('fd-1').classList.add('failed');\n  document.getElementById('fd-1-label').textContent = 'Hardware fault detected';\n  document.getElementById('fd-2').classList.add('active-glow');\n  document.getElementById('fd-2-label').textContent = '4 instances running (+2 moved)';\n  const log = document.getElementById('fdLog');\n  log.classList.remove('hidden');\n  log.innerHTML = '\u26a0 Rack-level failure isolated to FD-1. Workloads scheduled in FD-2/FD-3 were never affected \u2014 this is fault isolation in action.';\n  addXP(20,'Fault domain isolation observed');\n}\n\n/* ================= MISSION 1: CREATE ACCOUNT ================= */\nfunction renderM1(){\n  const done = STATE.done.has('m1');\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Mission 1 \u00b7 100 XP</div>\n    <h1 class=\"page-title\">Create Your OCI Free Tier Account</h1>\n    <p class=\"page-sub\">Simulated signup \u2014 no real account is created. This mirrors the exact steps of cloud.oracle.com/free.</p>\n  </div>\n  <div class=\"card\" style=\"max-width:520px;\">\n    ${done ? `<div class=\"pill pill-green\" style=\"margin-bottom:14px;\">\u2713 Account Created Successfully</div>` : ''}\n    <div class=\"field\"><label>Email Address</label><input id=\"m1email\" placeholder=\"you@company.com\" ${done?'disabled':''}></div>\n    <div class=\"field\"><label>Country</label><select id=\"m1country\" ${done?'disabled':''}><option>India</option><option>United States</option><option>United Kingdom</option><option>Germany</option><option>Australia</option></select></div>\n    <div class=\"field\"><label>Password</label><input type=\"password\" id=\"m1pass\" placeholder=\"Minimum 12 characters\" ${done?'disabled':''}></div>\n    <div class=\"field\"><label>Phone Number (for verification)</label><input id=\"m1phone\" placeholder=\"+91 XXXXX XXXXX\" ${done?'disabled':''}></div>\n    <div class=\"field\"><label>Card (verification only \u2014 never charged on Free Tier)</label><input id=\"m1card\" placeholder=\"XXXX XXXX XXXX XXXX\" ${done?'disabled':''}></div>\n    ${!done ? `<button class=\"btn btn-primary\" style=\"width:100%;justify-content:center;\" onclick=\"submitM1()\">Start for Free \u2192</button>` : `<button class=\"btn btn-ghost\" style=\"width:100%;justify-content:center;\" onclick=\"setView('missionmap')\">Continue to Mission Map</button>`}\n  </div>\n  ${done ? renderQuizBlock('m1') : ''}`;\n}\nfunction submitM1(){\n  const email = document.getElementById('m1email').value.trim();\n  const phone = document.getElementById('m1phone').value.trim();\n  const card = document.getElementById('m1card').value.trim();\n  const pass = document.getElementById('m1pass').value.trim();\n  if(!email || !email.includes('@')){ toast('err','Invalid email','Enter a valid email address.'); return; }\n  if(pass.length<8){ toast('err','Weak password','Use at least 8 characters.'); return; }\n  if(!phone){ toast('err','Phone required','Phone verification is mandatory.'); return; }\n  if(!card){ toast('err','Card required','Card verification is mandatory (no charge on Free Tier).'); return; }\n  toast('info','Sending verification code\u2026','Simulated SMS + email verification');\n  setTimeout(()=>{\n    completeMission('m1',100);\n    renderMain();\n  }, 900);\n}\n\n/* ================= MISSION 2: COMPARTMENTS ================= */\nconst M2_TARGETS = ['Development','Testing','Production'];\nfunction renderM2(){\n  const done = STATE.done.has('m2');\n  const allPlaced = M2_TARGETS.every(t=>STATE.m2.placed[t]);\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Mission 2 \u00b7 120 XP</div>\n    <h1 class=\"page-title\">Build the Compartment Hierarchy</h1>\n    <p class=\"page-sub\">Click a compartment chip, then click the Root compartment to place it. All three must be placed correctly.</p>\n  </div>\n  <div class=\"two-col\">\n    <div class=\"card\">\n      <h4 style=\"margin-bottom:12px;\">Compartments to create</h4>\n      <div class=\"tag-list\" id=\"m2chips\">\n        ${M2_TARGETS.map(t=>`<div class=\"drag-chip ${STATE.m2.placed[t]?'placed':''}\" onclick=\"selectM2Chip('${t}', this)\">\ud83d\udcc1 ${t}</div>`).join('')}\n      </div>\n      <div class=\"info-box\">\ud83d\udca1 In real OCI, compartments are created via Identity \u2192 Compartments \u2192 Create Compartment, always with a parent selected.</div>\n    </div>\n    <div class=\"card\">\n      <h4 style=\"margin-bottom:12px;\">Root Compartment (Tenancy)</h4>\n      <div class=\"dropzone\" id=\"m2drop\" onclick=\"placeInRoot()\">\n        <span style=\"color:var(--text-faint); font-size:12px;\">${Object.keys(STATE.m2.placed).length===0?'Select a chip, then click here to place it under Root':''}</span>\n        ${Object.keys(STATE.m2.placed).map(t=>`<div class=\"pill pill-green\">\ud83d\udcc1 ${t}</div>`).join('')}\n      </div>\n    </div>\n  </div>\n  ${allPlaced && !done ? `<div style=\"margin-top:16px;\"><button class=\"btn btn-primary\" onclick=\"completeMission('m2',120); renderMain();\">\u2713 Confirm Hierarchy &amp; Complete Mission</button></div>` : ''}\n  ${done ? renderQuizBlock('m2') : ''}`;\n}\nfunction selectM2Chip(name, el){\n  if(STATE.m2.placed[name]) return;\n  document.querySelectorAll('#m2chips .drag-chip').forEach(c=>c.style.outline='');\n  STATE.selectedChip = name;\n  el.style.outline = '2px solid var(--blue)';\n}\nfunction placeInRoot(){\n  if(!STATE.selectedChip){ toast('err','Nothing selected','Select a compartment chip first.'); return; }\n  STATE.m2.placed[STATE.selectedChip] = true;\n  toast('ok','Compartment placed', STATE.selectedChip+' \u2192 Root');\n  STATE.selectedChip = null;\n  renderMain();\n}\n\n/* ================= MISSION 3: CREATE USERS ================= */\nconst M3_TARGETS = [\n  {u:'AdminUser', desc:'Full administrative access'},\n  {u:'DevUser', desc:'Application developer'},\n  {u:'Auditor', desc:'Read-only compliance reviewer'},\n];\nfunction renderM3(){\n  const done = STATE.done.has('m3');\n  const createdCount = Object.keys(STATE.m3.created).length;\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Mission 3 \u00b7 120 XP</div>\n    <h1 class=\"page-title\">Create OCI Users</h1>\n    <p class=\"page-sub\">Use the User Creation Wizard to provision three identities.</p>\n  </div>\n  <div class=\"two-col\">\n    <div class=\"card\">\n      <h4 style=\"margin-bottom:12px;\">User Creation Wizard</h4>\n      <div class=\"field\"><label>Username</label><select id=\"m3user\">${M3_TARGETS.filter(t=>!STATE.m3.created[t.u]).map(t=>`<option value=\"${t.u}\">${t.u}</option>`).join('') || '<option>All users created</option>'}</select></div>\n      <div class=\"field\"><label>Description</label><input id=\"m3desc\" placeholder=\"e.g. Application developer\"></div>\n      <div class=\"field\"><label>Email</label><input id=\"m3mail\" placeholder=\"user@company.com\"></div>\n      <button class=\"btn btn-primary\" ${createdCount>=3?'disabled':''} onclick=\"createM3User()\">+ Create User</button>\n    </div>\n    <div class=\"card\">\n      <h4 style=\"margin-bottom:12px;\">Provisioned Users (${createdCount}/3)</h4>\n      <div id=\"m3cards\" style=\"display:flex; flex-direction:column; gap:10px;\">\n        ${Object.keys(STATE.m3.created).map(u=>{\n          const t = M3_TARGETS.find(x=>x.u===u);\n          return `<div class=\"card\" style=\"padding:12px;\"><b>${u}</b><div class=\"page-sub\">${t.desc}</div><span class=\"pill pill-green\" style=\"margin-top:6px;\">\ud83d\udd11 Password generated \u2014 download credentials</span></div>`;\n        }).join('') || '<p class=\"page-sub\">No users yet.</p>'}\n      </div>\n    </div>\n  </div>\n  ${createdCount>=3 && !done ? `<div style=\"margin-top:16px;\"><button class=\"btn btn-primary\" onclick=\"completeMission('m3',120); renderMain();\">\u2713 Complete Mission</button></div>` : ''}\n  ${done ? renderQuizBlock('m3') : ''}`;\n}\nfunction createM3User(){\n  const sel = document.getElementById('m3user');\n  const u = sel.value;\n  const mail = document.getElementById('m3mail').value.trim();\n  if(!M3_TARGETS.find(t=>t.u===u)) return;\n  if(!mail || !mail.includes('@')){ toast('err','Email required','Enter a valid email for the new user.'); return; }\n  STATE.m3.created[u] = {email:mail};\n  toast('ok','User created', u+' \u2014 a one-time password has been generated');\n  renderMain();\n}\n\n/* ================= MISSION 4: GROUPS ================= */\nconst M4_TARGETS = ['Administrators','Developers','Auditors'];\nfunction renderM4(){\n  const done = STATE.done.has('m4');\n  const count = Object.keys(STATE.m4.created).length;\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Mission 4 \u00b7 100 XP</div>\n    <h1 class=\"page-title\">Create IAM Groups</h1>\n    <p class=\"page-sub\">Groups let you manage permissions once, for many users. Drag each group card into the IAM panel.</p>\n  </div>\n  <div class=\"two-col\">\n    <div class=\"card\">\n      <h4 style=\"margin-bottom:12px;\">Groups to create</h4>\n      <div class=\"tag-list\">\n        ${M4_TARGETS.map(g=>`<div class=\"drag-chip ${STATE.m4.created[g]?'placed':''}\" onclick=\"createM4Group('${g}')\">\ud83d\udc65 ${g}</div>`).join('')}\n      </div>\n    </div>\n    <div class=\"card\">\n      <h4 style=\"margin-bottom:12px;\">IAM Panel \u2014 Groups (${count}/3)</h4>\n      <div class=\"dropzone\">${Object.keys(STATE.m4.created).map(g=>`<div class=\"pill pill-blue\">\ud83d\udc65 ${g}</div>`).join('') || '<span style=\"color:var(--text-faint); font-size:12px;\">No groups yet \u2014 click a chip to add it here.</span>'}</div>\n    </div>\n  </div>\n  <div class=\"info-box\">\ud83d\udca1 Groups simplify permission management: write one policy per group instead of one per user.</div>\n  ${count>=3 && !done ? `<div style=\"margin-top:16px;\"><button class=\"btn btn-primary\" onclick=\"completeMission('m4',100); renderMain();\">\u2713 Complete Mission</button></div>` : ''}\n  ${done ? renderQuizBlock('m4') : ''}`;\n}\nfunction createM4Group(g){\n  if(STATE.m4.created[g]) return;\n  STATE.m4.created[g] = true;\n  toast('ok','Group created', g);\n  renderMain();\n}\n\n/* ================= MISSION 5: ASSIGN USERS ================= */\nconst M5_MAP = {AdminUser:'Administrators', DevUser:'Developers', Auditor:'Auditors'};\nfunction renderM5(){\n  const done = STATE.done.has('m5');\n  const users = Object.keys(M5_MAP);\n  const assignedCount = Object.keys(STATE.m5.assigned).length;\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Mission 5 \u00b7 130 XP</div>\n    <h1 class=\"page-title\">Assign Users to Groups</h1>\n    <p class=\"page-sub\">Select a user, then click the correct group. Wrong assignments will shake and bounce back.</p>\n  </div>\n  <div class=\"two-col\">\n    <div class=\"card\">\n      <h4 style=\"margin-bottom:12px;\">Users</h4>\n      <div class=\"tag-list\">\n        ${users.map(u=>`<div class=\"drag-chip ${STATE.m5.assigned[u]?'placed':''}\" onclick=\"selectM5User('${u}', this)\">\ud83d\udc64 ${u}</div>`).join('')}\n      </div>\n    </div>\n    <div class=\"card\">\n      <h4 style=\"margin-bottom:12px;\">Groups</h4>\n      <div style=\"display:flex; flex-direction:column; gap:10px;\">\n        ${M4_TARGETS.map(g=>`<div class=\"dropzone\" id=\"m5-${g}\" style=\"min-height:50px;\" onclick=\"assignM5('${g}')\">\n          <b style=\"width:100%;\">${g}</b>\n          ${users.filter(u=>STATE.m5.assigned[u]===g).map(u=>`<span class=\"pill pill-green\">${u}</span>`).join('')}\n        </div>`).join('')}\n      </div>\n    </div>\n  </div>\n  ${assignedCount>=3 ? `\n  <div class=\"card\" style=\"margin-top:16px;\">\n    <h4 style=\"margin-bottom:10px;\">Relationship Graph</h4>\n    <div class=\"rgraph\">\n      <div class=\"rg-col\">${users.map(u=>`<div class=\"rg-node\">\ud83d\udc64 ${u}</div>`).join('')}</div>\n      <div class=\"rg-arrow\">\u2192</div>\n      <div class=\"rg-col\">${M4_TARGETS.map(g=>`<div class=\"rg-node\">\ud83d\udc65 ${g}</div>`).join('')}</div>\n      <div class=\"rg-arrow\">\u2192</div>\n      <div class=\"rg-col\"><div class=\"rg-node\">\ud83d\udcdc Policies</div></div>\n    </div>\n  </div>` : ''}\n  ${assignedCount>=3 && !done ? `<div style=\"margin-top:16px;\"><button class=\"btn btn-primary\" onclick=\"completeMission('m5',130); renderMain();\">\u2713 Complete Mission</button></div>` : ''}\n  ${done ? renderQuizBlock('m5') : ''}`;\n}\nfunction selectM5User(u, el){\n  if(STATE.m5.assigned[u]) return;\n  document.querySelectorAll('#main .drag-chip').forEach(c=>c.style.outline='');\n  STATE.selectedChip = u;\n  el.style.outline = '2px solid var(--blue)';\n}\nfunction assignM5(group){\n  if(!STATE.selectedChip){ toast('err','Select a user first',''); return; }\n  const user = STATE.selectedChip;\n  const zone = document.getElementById('m5-'+group);\n  if(M5_MAP[user] === group){\n    STATE.m5.assigned[user] = group;\n    zone.classList.add('correct');\n    toast('ok','Correct assignment', `${user} \u2192 ${group}`);\n    STATE.selectedChip = null;\n    renderMain();\n  } else {\n    zone.classList.add('wrong');\n    toast('err','Wrong group', `${user} does not belong in ${group}`);\n    setTimeout(()=>zone.classList.remove('wrong'), 450);\n  }\n}\n\n/* ================= MISSION 6: POLICY BUILDER ================= */\nconst M6_STATEMENTS = [\n  {parts:['Allow','group Developers','to manage','instance-family','in compartment Development']},\n  {parts:['Allow','group Auditors','to inspect','all-resources','in tenancy']},\n  {parts:['Allow','group Administrators','to manage','all-resources','in tenancy']},\n];\nfunction renderM6(){\n  const done = STATE.done.has('m6');\n  const count = Object.keys(STATE.m6.written).length;\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Mission 6 \u00b7 150 XP</div>\n    <h1 class=\"page-title\">IAM Policy Builder</h1>\n    <p class=\"page-sub\">Click \"Write Statement\" to type each policy into the editor, then click any keyword to see what it means.</p>\n  </div>\n  <div class=\"policy-editor\" id=\"policyEditor\" style=\"margin-bottom:16px;\">\n    ${Object.keys(STATE.m6.written).map(i=>renderPolicyLine(M6_STATEMENTS[i].parts)).join('') || '<span style=\"color:#5f6b7a;\">-- policies will appear here --</span>'}\n  </div>\n  <div class=\"tag-list\" style=\"margin-bottom:16px;\">\n    ${M6_STATEMENTS.map((s,i)=>`<button class=\"btn btn-ghost btn-sm\" ${STATE.m6.written[i]?'disabled':''} onclick=\"writeM6(${i})\">${STATE.m6.written[i]?'\u2713 ':''}Write Statement ${i+1}</button>`).join('')}\n  </div>\n  <div class=\"card\">\n    <h4 style=\"margin-bottom:10px;\">Keyword Glossary (click a colored word above)</h4>\n    <div id=\"keywordGloss\" class=\"page-sub\">Click any highlighted keyword in a written policy to see its explanation here.</div>\n  </div>\n  <div class=\"mistake-box\" style=\"margin-top:14px;\">\u26a0 Common mistake: misspelling <b>Allow</b>, forgetting <b>group</b>, or omitting <b>in compartment</b>/<b>in tenancy</b> scope \u2014 any of these breaks the statement.</div>\n  ${count>=3 && !done ? `<div style=\"margin-top:16px;\"><button class=\"btn btn-primary\" onclick=\"completeMission('m6',150); renderMain();\">\u2713 Complete Mission</button></div>` : ''}\n  ${done ? renderQuizBlock('m6') : ''}`;\n}\nconst KEYWORD_INFO = {\n  'Allow':'Every OCI policy statement must start with the keyword Allow.',\n  'to manage':'\"manage\" is the highest verb \u2014 full control including create, update, delete.',\n  'to inspect':'\"inspect\" is the lowest verb \u2014 list resources and view basic metadata only, no read of contents.',\n  'in compartment Development':'Scopes the statement to only the Development compartment \u2014 not its siblings.',\n  'in tenancy':'Scopes the statement to the entire tenancy \u2014 every compartment, including root.',\n};\nfunction renderPolicyLine(parts){\n  const cls = ['tok-allow','tok-group','tok-verb','tok-resource','tok-scope'];\n  return `<div class=\"line\">${parts.map((p,i)=>`<span class=\"${cls[i]}\" style=\"cursor:pointer;\" onclick=\"showKeyword('${p.replace(/'/g,\"\\\\'\")}')\">${p}</span>`).join(' ')}</div>`;\n}\nfunction writeM6(i){\n  if(STATE.m6.written[i]) return;\n  STATE.m6.written[i] = true;\n  toast('ok','Policy statement added', 'Statement '+(i+1));\n  renderMain();\n}\nfunction showKeyword(word){\n  const info = KEYWORD_INFO[word] || (word.startsWith('group') ? 'References an IAM Group \u2014 the policy applies to every member of that group.' : 'Part of the policy statement scope/subject.');\n  document.getElementById('keywordGloss').innerHTML = `<b>${word}</b> \u2014 ${info}`;\n}\n\n/* ================= MISSION 7: POLICY SIMULATOR ================= */\nconst M7_ACTIONS = [\n  {a:'Create Compute Instance', needs:'manage', scope:'Development'},\n  {a:'Delete Compartment', needs:'manage', scope:'tenancy-admin-only'},\n  {a:'Read Policies', needs:'inspect', scope:'tenancy'},\n  {a:'Create VCN', needs:'manage', scope:'Development'},\n  {a:'Delete Instance', needs:'manage', scope:'Development'},\n  {a:'Create Bucket', needs:'manage', scope:'Development'},\n];\nconst M7_PERMS = {\n  AdminUser:{verb:'manage', scope:'tenancy'},\n  DevUser:{verb:'manage', scope:'Development'},\n  Auditor:{verb:'inspect', scope:'tenancy'},\n};\nfunction renderM7(){\n  const done = STATE.done.has('m7');\n  const role = STATE.m7.role;\n  const testedCount = Object.keys(STATE.m7.tested).length;\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Mission 7 \u00b7 150 XP</div>\n    <h1 class=\"page-title\">Policy Simulator</h1>\n    <p class=\"page-sub\">Switch roles and try actions. See exactly why OCI allows or denies each one.</p>\n  </div>\n  <div class=\"card\" style=\"margin-bottom:16px;\">\n    <h4 style=\"margin-bottom:10px;\">Login as</h4>\n    <div class=\"tag-list\">\n      ${Object.keys(M7_PERMS).map(u=>`<button class=\"btn ${role===u?'btn-primary':'btn-ghost'} btn-sm\" onclick=\"setM7Role('${u}')\">${u}</button>`).join('')}\n    </div>\n  </div>\n  <div class=\"grid grid-3\">\n    ${M7_ACTIONS.map((act,i)=>`\n      <div class=\"card\">\n        <h5 style=\"font-size:13px; margin-bottom:8px;\">${act.a}</h5>\n        <button class=\"btn btn-ghost btn-sm\" onclick=\"testM7(${i})\">Attempt as ${role}</button>\n        <div id=\"m7res-${i}\" style=\"margin-top:10px; font-size:12px;\"></div>\n      </div>`).join('')}\n  </div>\n  <div class=\"card\" style=\"margin-top:16px;\">\n    <h4 style=\"margin-bottom:10px;\">Evaluation Flow</h4>\n    <div class=\"rgraph\"><div class=\"rg-node\">User</div><div class=\"rg-arrow\">\u2193</div></div>\n    <div class=\"rgraph\" style=\"margin-top:-30px;\"><div class=\"rg-node\">Group</div><div class=\"rg-arrow\">\u2193</div></div>\n    <div class=\"rgraph\" style=\"margin-top:-30px;\"><div class=\"rg-node\">Policy</div><div class=\"rg-arrow\">\u2193</div></div>\n    <div class=\"rgraph\" style=\"margin-top:-30px;\"><div class=\"rg-node\">Decision (Allow / Deny)</div></div>\n  </div>\n  ${testedCount>=4 && !done ? `<div style=\"margin-top:16px;\"><button class=\"btn btn-primary\" onclick=\"completeMission('m7',150); renderMain();\">\u2713 Complete Mission</button></div>` : ''}\n  ${done ? renderQuizBlock('m7') : ''}`;\n}\nfunction setM7Role(u){ STATE.m7.role = u; renderMain(); }\nfunction testM7(i){\n  const act = M7_ACTIONS[i];\n  const perm = M7_PERMS[STATE.m7.role];\n  const verbRank = {inspect:1, read:2, use:3, manage:4};\n  let allowed;\n  if(act.scope==='tenancy-admin-only'){\n    allowed = STATE.m7.role==='AdminUser';\n  } else {\n    const scopeOk = perm.scope==='tenancy' || perm.scope===act.scope;\n    allowed = scopeOk && verbRank[perm.verb] >= verbRank[act.needs];\n  }\n  STATE.m7.tested[STATE.m7.role+'-'+i] = true;\n  const reason = allowed\n    ? `${STATE.m7.role} has \"${perm.verb}\" scoped to ${perm.scope}, which covers ${act.needs} on ${act.scope}.`\n    : `${STATE.m7.role} has \"${perm.verb}\" scoped to ${perm.scope} \u2014 not enough to ${act.needs} on ${act.scope}.`;\n  document.getElementById('m7res-'+i).innerHTML = `<span class=\"pill ${allowed?'pill-green':'pill-red'}\">${allowed?'\u2713 Allowed':'\u26d4 Denied'}</span><p class=\"page-sub\" style=\"margin-top:8px;\">${reason}</p>`;\n  if(Object.keys(STATE.m7.tested).length>=4) renderSidebar();\n  addXP(5,'Policy tested');\n}\n\n/* ================= MISSION 8: CLI ================= */\nfunction renderM8(){\n  const done = STATE.done.has('m8');\n  const step = STATE.m8.step;\n  afterRenderHooks.m8 = ()=>{ const t=document.getElementById('terminal'); if(t) t.scrollTop = t.scrollHeight; };\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Mission 8 \u00b7 130 XP</div>\n    <h1 class=\"page-title\">OCI CLI \u2014 Cloud Shell</h1>\n    <p class=\"page-sub\">Run each command in order. Click \"Run\" to execute it in the simulated Cloud Shell.</p>\n  </div>\n  <div class=\"terminal\" id=\"terminal\">\n    ${STATE.m8.history.map(h=>`<div class=\"line\"><span class=\"prompt\">$</span> ${h.cmd}</div><div class=\"line out\">${h.out.replace(/\\n/g,'<br>')}</div><div class=\"line comment\">${h.note}</div>`).join('')}\n    ${step<CLI_STEPS.length ? `<div class=\"line\"><span class=\"prompt\">$</span> <span style=\"color:var(--text-faint);\">${CLI_STEPS[step].cmd}</span></div>` : ''}\n  </div>\n  <div style=\"margin-top:14px;\">\n    ${step<CLI_STEPS.length ? `<button class=\"btn btn-primary\" onclick=\"runM8Step()\">\u25b6 Run: ${CLI_STEPS[step].cmd}</button>` : `<span class=\"pill pill-green\">All commands executed</span>`}\n  </div>\n  ${step>=CLI_STEPS.length && !done ? `<div style=\"margin-top:16px;\"><button class=\"btn btn-primary\" onclick=\"completeMission('m8',130); renderMain();\">\u2713 Complete Mission</button></div>` : ''}\n  ${done ? renderQuizBlock('m8') : ''}`;\n}\nfunction runM8Step(){\n  const s = CLI_STEPS[STATE.m8.step];\n  STATE.m8.history.push(s);\n  STATE.m8.step++;\n  addXP(10, s.cmd);\n  renderMain();\n}\n\n/* ================= CLI CONFIG SIMULATOR ================= */\nconst CLI_CONFIG_FIELDS = [\n  {key:'tenancy', label:'Tenancy OCID', ph:'ocid1.tenancy.oc1..aaaaaaaa...'},\n  {key:'user', label:'User OCID', ph:'ocid1.user.oc1..aaaaaaaa...'},\n  {key:'region', label:'Region', ph:'us-ashburn-1'},\n  {key:'fingerprint', label:'Fingerprint', ph:'a1:b2:c3:d4:...'},\n  {key:'key_file', label:'Private Key Path', ph:'~/.oci/oci_api_key.pem'},\n];\nfunction renderCliConfig(){\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">CLI Configuration Simulator</div>\n    <h1 class=\"page-title\">Build ~/.oci/config</h1>\n    <p class=\"page-sub\">Paste each value. This mirrors the \"oci setup config\" wizard.</p>\n  </div>\n  <div class=\"two-col\">\n    <div class=\"card\">\n      ${CLI_CONFIG_FIELDS.map(f=>`<div class=\"field\"><label>${f.label}</label><input id=\"cfg-${f.key}\" placeholder=\"${f.ph}\" oninput=\"updateCliConfig()\"></div>`).join('')}\n    </div>\n    <div class=\"card\">\n      <h4 style=\"margin-bottom:10px;\">~/.oci/config</h4>\n      <div class=\"terminal\" id=\"cliConfigPreview\" style=\"min-height:180px;\">[DEFAULT]<br>tenancy=<br>user=<br>region=<br>fingerprint=<br>key_file=</div>\n      <div id=\"cliConfigExplain\" class=\"info-box\" style=\"margin-top:12px;\">Fill in each field \u2014 every one is explained here as you type.</div>\n    </div>\n  </div>`;\n}\nfunction updateCliConfig(){\n  const vals = {};\n  CLI_CONFIG_FIELDS.forEach(f=>{ vals[f.key] = document.getElementById('cfg-'+f.key).value || ''; });\n  document.getElementById('cliConfigPreview').innerHTML =\n    `[DEFAULT]<br>tenancy=${vals.tenancy}<br>user=${vals.user}<br>region=${vals.region}<br>fingerprint=${vals.fingerprint}<br>key_file=${vals.key_file}`;\n  const filled = Object.values(vals).filter(v=>v.trim()).length;\n  if(filled===5 && !STATE.cliConfigDone){\n    STATE.cliConfigDone = true;\n    addXP(40,'CLI config completed');\n  }\n  const explains = {\n    tenancy:'Uniquely identifies your OCI tenancy \u2014 found on the Tenancy Details page.',\n    user:'Uniquely identifies the IAM user the CLI authenticates as.',\n    region:'The default region CLI commands run against.',\n    fingerprint:'A hash of your public API key, generated when you add the key to your user.',\n    key_file:'Local path to the private key half of your API signing key pair \u2014 never share this file.',\n  };\n  const last = CLI_CONFIG_FIELDS.slice().reverse().find(f=>vals[f.key].trim());\n  if(last) document.getElementById('cliConfigExplain').innerHTML = `<b>${last.label}:</b> ${explains[last.key]}`;\n}\n\n/* ================= CHALLENGES ================= */\nfunction renderChallenges(){\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Real-World Challenges</div>\n    <h1 class=\"page-title\">Troubleshooting Scenarios</h1>\n    <p class=\"page-sub\">Diagnose each real-world IAM problem. ${STATE.challengesDone.size}/5 solved.</p>\n  </div>\n  ${CHALLENGES.map(c=>`\n    <div class=\"card\" style=\"margin-bottom:14px;\">\n      <h4 style=\"margin-bottom:6px;\">${c.title} ${STATE.challengesDone.has(c.id)?'<span class=\"pill pill-green\">Solved</span>':''}</h4>\n      <p class=\"page-sub\" style=\"margin-bottom:12px;\">${c.scenario}</p>\n      <div id=\"chal-${c.id}\">\n        ${c.opts.map((o,i)=>`<div class=\"q-opt\" onclick=\"answerChallenge('${c.id}',${i})\">${o}</div>`).join('')}\n        <div class=\"q-explain\" id=\"chalex-${c.id}\">${c.ex}</div>\n      </div>\n    </div>`).join('')}`;\n}\nfunction answerChallenge(id, idx){\n  const c = CHALLENGES.find(x=>x.id===id);\n  const container = document.getElementById('chal-'+id);\n  const opts = container.querySelectorAll('.q-opt');\n  opts.forEach((o,i)=>{\n    o.onclick = null;\n    if(i===c.a) o.classList.add('correct');\n    else if(i===idx) o.classList.add('incorrect');\n  });\n  document.getElementById('chalex-'+id).classList.add('show');\n  if(idx===c.a){\n    if(!STATE.challengesDone.has(id)){ STATE.challengesDone.add(id); addXP(30, c.title+' solved'); }\n  } else {\n    toast('err','Not quite','Check the explanation below.');\n  }\n  renderSidebar();\n}\n\n/* ================= ACHIEVEMENTS ================= */\nfunction renderAchievements(){\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Achievements</div>\n    <h1 class=\"page-title\">Trophy Case</h1>\n    <p class=\"page-sub\">${STATE.achUnlocked.size}/${ACHIEVEMENTS.length} unlocked</p>\n  </div>\n  <div class=\"grid grid-4\">\n    ${ACHIEVEMENTS.map(a=>{\n      const unlocked = STATE.achUnlocked.has(a.id);\n      return `<div class=\"ach-card ${unlocked?'':'locked'}\"><div class=\"ico\">${a.ico}</div><h5>${a.name}</h5><p>${unlocked?'Unlocked':a.cond}</p></div>`;\n    }).join('')}\n  </div>`;\n}\n\n/* ================= DASHBOARD ================= */\nfunction renderDashboard(){\n  const quizTotal = Object.values(STATE.quizScores).reduce((a,b)=>a+b,0);\n  const cliCount = STATE.m8.history.length;\n  const policyCount = Object.keys(STATE.m6.written).length;\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Dashboard</div>\n    <h1 class=\"page-title\">Your Progress</h1>\n  </div>\n  <div class=\"grid grid-4\">\n    <div class=\"card\"><div class=\"pill pill-red\">Mission Progress</div><h2 style=\"margin-top:10px;\">${STATE.done.size}/8</h2></div>\n    <div class=\"card\"><div class=\"pill pill-blue\">Quiz Score</div><h2 style=\"margin-top:10px;\">${quizTotal} correct</h2></div>\n    <div class=\"card\"><div class=\"pill pill-green\">Labs Completed</div><h2 style=\"margin-top:10px;\">${STATE.done.size}</h2></div>\n    <div class=\"card\"><div class=\"pill pill-orange\">CLI Commands</div><h2 style=\"margin-top:10px;\">${cliCount}</h2></div>\n    <div class=\"card\"><div class=\"pill pill-blue\">Policies Written</div><h2 style=\"margin-top:10px;\">${policyCount}</h2></div>\n    <div class=\"card\"><div class=\"pill pill-green\">Challenges Solved</div><h2 style=\"margin-top:10px;\">${STATE.challengesDone.size}/5</h2></div>\n    <div class=\"card\"><div class=\"pill pill-red\">Current Rank</div><h2 style=\"margin-top:10px; font-size:18px;\">${rankFor(STATE.xp)}</h2></div>\n    <div class=\"card\"><div class=\"pill pill-orange\">Total XP</div><h2 style=\"margin-top:10px;\">${STATE.xp}</h2></div>\n  </div>`;\n}\n\n/* ================= CAPSTONE ================= */\nfunction renderCapstone(){\n  const allDone = MISSION_ORDER.every(m=>STATE.done.has(m));\n  const checklist = [\n    {label:'Create compartments (Dev/Test/Prod)', ok:STATE.done.has('m2')},\n    {label:'Create users (Admin/Dev/Auditor)', ok:STATE.done.has('m3')},\n    {label:'Create groups', ok:STATE.done.has('m4')},\n    {label:'Assign users to groups', ok:STATE.done.has('m5')},\n    {label:'Write IAM policies', ok:STATE.done.has('m6')},\n    {label:'Test permissions in simulator', ok:STATE.done.has('m7')},\n    {label:'Run CLI identity commands', ok:STATE.done.has('m8')},\n  ];\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">Final Capstone</div>\n    <h1 class=\"page-title\">Enterprise IAM Build-Out</h1>\n    <p class=\"page-sub\">Scenario: a company with three environments (Dev/Test/Prod) and three employees (Administrator/Developer/Auditor) needs a complete identity architecture.</p>\n  </div>\n  <div class=\"card\">\n    ${checklist.map(c=>`<div style=\"display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid var(--border-soft);\">\n      <span class=\"pill ${c.ok?'pill-green':'pill-gray'}\">${c.ok?'\u2713':'\u25cb'}</span><span>${c.label}</span></div>`).join('')}\n  </div>\n  ${allDone ? `\n  <div class=\"card\" style=\"text-align:center; margin-top:18px; padding:44px; background:linear-gradient(180deg, rgba(61,220,132,.12), var(--panel));\">\n    <div style=\"font-size:44px;margin-bottom:10px;\">\ud83c\udf93</div>\n    <h2 style=\"margin-bottom:8px;\">Mission Complete \u2014 OCI IAM Expert</h2>\n    <p class=\"page-sub\" style=\"margin-bottom:14px;\">Certification Ready \u00b7 XP ${STATE.xp}</p>\n    <div class=\"pill pill-green\" style=\"font-size:13px; padding:8px 16px;\">Certification Ready</div>\n  </div>` : `<div class=\"tip-box\" style=\"margin-top:16px;\">Complete all 8 missions to unlock your capstone certificate.</div>`}`;\n}\n\n/* ================= QUIZ BLOCK (reused per mission) ================= */\nfunction renderQuizBlock(missionId){\n  const qs = QUIZZES[missionId];\n  if(!qs) return '';\n  const answered = STATE.quizAnswered[missionId] || {};\n  return `\n  <div class=\"card\" style=\"margin-top:20px;\">\n    <h4 style=\"margin-bottom:14px;\">\ud83c\udfaf Knowledge Check</h4>\n    ${qs.map((q,qi)=>`\n      <div class=\"quiz-q\">\n        <div class=\"q-txt\">${qi+1}. ${q.q}</div>\n        ${q.opts.map((o,oi)=>`<div class=\"q-opt ${answered[qi]===oi?(oi===q.a?'correct':'incorrect'):''}\" onclick=\"answerQuiz('${missionId}',${qi},${oi})\">${o}</div>`).join('')}\n        <div class=\"q-explain ${answered[qi]!==undefined?'show':''}\">${q.ex}</div>\n      </div>`).join('')}\n  </div>`;\n}\nfunction answerQuiz(missionId, qi, oi){\n  if(!STATE.quizAnswered[missionId]) STATE.quizAnswered[missionId] = {};\n  if(STATE.quizAnswered[missionId][qi] !== undefined) return;\n  STATE.quizAnswered[missionId][qi] = oi;\n  const q = QUIZZES[missionId][qi];\n  if(oi===q.a){\n    STATE.quizScores[missionId] = (STATE.quizScores[missionId]||0)+1;\n    addXP(10,'Correct answer');\n  } else {\n    toast('err','Not quite','Review the explanation.');\n  }\n  renderMain();\n}\n\n/* ================= INIT ================= */\nfunction toggleTheme(){\n  STATE.theme = STATE.theme==='dark' ? 'light' : 'dark';\n  document.body.setAttribute('data-theme', STATE.theme);\n}\ndocument.getElementById('themeToggle').addEventListener('click', toggleTheme);\nrenderSidebar();\nrenderMain();\nwindow.STATE = STATE; // debug/introspection hook\n\n"};
